  var price = PRICE_TABLE[unit];        // 取单价 / unit price
  var threshold = LIMITS.threshold;    // 阈值 / discount threshold
  if (qty > threshold) {
    price = price * (1 - LIMITS.discount);   // 折扣 / discount
  }
